const D = { energy: .6, scale: 1, speed: 1, coupling: .55, spread: .28, density: .5, cores: 3, hue: 200, x: .5, y: .5, style: 'phase-wheel', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
