const GH = clp(Math.round(LS * H / Math.max(W, H)), 40, 104) | 0;
const N = GW * GH;
const cores = clp(Math.round(P.cores), 1, 8) | 0;

// ---- (re)build phase field + natural-freq heterogeneity on size / seed / cores change ----
const key = GW + 'x' + GH + '_' + seedI + '_' + cores;
if (S.key !== key || !S.ph) {
  S.key = key;
  S.ph = new Float32Array(N); S.ph2 = new Float32Array(N);
  S.si = new Float32Array(N); S.co = new Float32Array(N);
  S.omN = new Float32Array(N);
  // plant `cores` topological phase singularities -> immediate rotating spirals
  const cx = new Float32Array(cores), cy = new Float32Array(cores), ch = new Float32Array(cores);
  for (let c = 0; c < cores; c++) {
    cx[c] = (0.15 + 0.7 * hsh(c * 3 + 1)) * GW + (P.x - 0.5) * 0.35 * GW;
    cy[c] = (0.15 + 0.7 * hsh(c * 3 + 2)) * GH + (P.y - 0.5) * 0.35 * GH;
    ch[c] = hsh(c * 3 + 3) > 0.5 ? 1 : -1;                 // random handedness
  }
  const kx = (hsh(91) - 0.5) * 0.11, ky = (hsh(92) - 0.5) * 0.11;   // planar phase gradient -> drift wind
  for (let y = 0; y < GH; y++) for (let x = 0; x < GW; x++) {
