    for (let c = 0; c < cores; c++) a += ch[c] * Math.atan2(y - cy[c], x - cx[c]);
    a += (hsh(i * 0.37 + 7) - 0.5) * 0.6;                  // symmetry-breaking noise
    S.ph[i] = a;
    S.omN[i] = hsh(i * 1.13 + 31) - 0.5;                   // per-cell natural-freq offset base
  }
  if (S.buf && S.buf.remove) S.buf.remove();
  S.buf = createGraphics(GW, GH); S.buf.pixelDensity(1);
  S.burn = 28;                                             // burn-in so first visible frame already shows spirals
}

// ---- live dynamics (read P every frame) ----
const dt = 0.11, omega0 = 0.26;
const spreadAmp = 0.30 + P.spread * 2.2;                   // natural-freq heterogeneity: order <-> turbulence
const secPhase = K.t * 0.045 + K.section * 0.7;
const Kc = (0.35 + P.coupling * 3.1) * (0.72 + 0.42 * Math.sin(secPhase)) + A.bass * 0.6;   // coupling breathes desync<->sync
const kcoef = Kc * dt / 8;
const si = S.si, co = S.co, omN = S.omN;

// ---- density-driven wandering pacemakers: implant fresh rotors so new spirals keep nucleating ----
const nInj = clp(Math.round(P.density * 5), 0, 6) | 0;
for (let q = 0; q < nInj; q++) {
  const wa = K.t * (0.1 + q * 0.05) + q * 2.399, rad = 0.15 + 0.12 * Math.sin(K.t * 0.04 + q * 1.3);
  const ix = ((0.5 + (P.x - 0.5) * 0.4 + Math.cos(wa) * rad) * GW) | 0;
  const iy = ((0.5 + (P.y - 0.5) * 0.4 + Math.sin(wa) * rad) * GH) | 0;
  const rr = 2, spin = K.t * 0.5 + (q & 1 ? 0 : Math.PI);
