    const xx = ((ix + dx) % GW + GW) % GW, yy = ((iy + dy) % GH + GH) % GH;
    S.ph[yy * GW + xx] = Math.atan2(dy, dx) * (q & 1 ? 1 : -1) + spin;   // topological singularity -> spiral source
  }
}

function stepSim() {
  const a = S.ph, b = S.ph2;
  for (let k = 0; k < N; k++) { const p = a[k]; si[k] = Math.sin(p); co[k] = Math.cos(p); }
  for (let y = 0; y < GH; y++) {
    const ym = (y - 1 + GH) % GH, yp = (y + 1) % GH, r0 = ym * GW, r1 = y * GW, r2 = yp * GW;
    for (let x = 0; x < GW; x++) {
      const xm = (x - 1 + GW) % GW, xp = (x + 1) % GW, i = r1 + x;
      const mS = si[r0 + xm] + si[r0 + x] + si[r0 + xp] + si[r1 + xm] + si[r1 + xp] + si[r2 + xm] + si[r2 + x] + si[r2 + xp];
      const mC = co[r0 + xm] + co[r0 + x] + co[r0 + xp] + co[r1 + xm] + co[r1 + xp] + co[r2 + xm] + co[r2 + x] + co[r2 + xp];
      const omg = omega0 + spreadAmp * omN[i];
      let np = a[i] + dt * omg + kcoef * (co[i] * mS - si[i] * mC);   // theta += w*dt + K*mean sin(dphase)
      np = np - TAU * Math.floor(np / TAU);                            // wrap for float precision
      b[i] = np;
    }
  }
  S.ph = b; S.ph2 = a;                                     // ping-pong
}

let steps = clp(Math.round((1 + P.speed * 1.7) * (0.6 + 0.7 * K.intensity)) + (S.burn || 0), 1, 9);
for (let s = 0; s < steps; s++) stepSim();
S.burn = 0;

// ---- recompute sin/cos of FINAL phases for coherence-lit render ----
{ const a = S.ph; for (let k = 0; k < N; k++) { const p = a[k]; si[k] = Math.sin(p); co[k] = Math.cos(p); } }

// ---- HSV -> rgb 0..255 into shared triple (no per-pixel alloc) ----
const OUT = [0, 0, 0];
function setHSV(h, s, v) {
  h = ((h % 360) + 360) % 360; const c = v * s, x = c * (1 - Math.abs((h / 60) % 2 - 1)), m = v - c;
  let r, g, b;
  if (h < 60) { r = c; g = x; b = 0; } else if (h < 120) { r = x; g = c; b = 0; } else if (h < 180) { r = 0; g = c; b = x; }
  else if (h < 240) { r = 0; g = x; b = c; } else if (h < 300) { r = x; g = 0; b = c; } else { r = c; g = 0; b = x; }
  OUT[0] = (r + m) * 255; OUT[1] = (g + m) * 255; OUT[2] = (b + m) * 255;
}

const hueOff = P.hue + K.section * 12 + K.t * 1.6;
const expo = clp(0.5 + P.energy * 0.9 + K.intensity * 0.22 + A.rms * 0.5, 0, 1.55);
