buf.loadPixels(); const px = buf.pixels;

for (let y = 0; y < GH; y++) {
  const ym = (y - 1 + GH) % GH, yp = (y + 1) % GH, r0 = ym * GW, r1 = y * GW, r2 = yp * GW;
  for (let x = 0; x < GW; x++) {
    const xm = (x - 1 + GW) % GW, xp = (x + 1) % GW, i = r1 + x;
    const mS = si[r0 + xm] + si[r0 + x] + si[r0 + xp] + si[r1 + xm] + si[r1 + xp] + si[r2 + xm] + si[r2 + x] + si[r2 + xp];
    const mC = co[r0 + xm] + co[r0 + x] + co[r0 + xp] + co[r1 + xm] + co[r1 + xp] + co[r2 + xm] + co[r2 + x] + co[r2 + xp];
    const rC = Math.min(1, Math.sqrt(mS * mS + mC * mC) / 8);   // local order parameter (1=synced interior, 0=defect/boundary)
    const p = ph[i], q = p / TAU;                              // 0..1 phase fraction
    if (style === 'ocean') {
      const hh = 150 + (0.5 + 0.5 * Math.cos(p)) * 105;
      setHSV(hh, 0.60 + 0.20 * rC, clp((0.24 + 0.52 * rC) * expo, 0.05, 0.96));
    } else if (style === 'ember') {
      const hh = 8 + (0.5 + 0.5 * Math.cos(p)) * 46;
      setHSV(hh, clp(0.98 - rC * 0.42, 0.4, 1), clp((0.15 + 0.64 * rC) * expo, 0.05, 0.98));
    } else if (style === 'duotone') {
      const bi = Math.floor(q * 6), parity = bi & 1;           // hard posterized 2-ink risograph bands
      const hh = hueOff + (parity ? 0 : 22);
      setHSV(hh, 0.30 + parity * 0.06, clp((parity ? 0.30 : 0.62) * (0.55 + 0.6 * rC) * expo, 0.05, 0.95));
    } else if (style === 'bioluminescent') {
      const f = q * 5, fr = f - Math.floor(f), lp = Math.min(fr, 1 - fr);
