      const defect = clp(1 - rC * 1.6, 0, 1) * 0.55;           // glowing defect network
      const glow = Math.max(line, defect);
      const hh = 150 + (0.5 + 0.5 * Math.cos(p)) * 40;
      setHSV(hh, 0.55 + 0.30 * glow, clp((0.07 + glow * 0.92) * expo, 0.04, 0.98));
    } else { // phase-wheel (default) -- full hue wheel, synced domains glow, defect veins darken
